// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.database.daoimport androidx.room.Daoimport androidx.room.Insertimport androidx.room.OnConflictStrategyimport androidx.room.Queryimport com.roshan.persona.database.entity.UndoActionEntity/** * NOUS — Undo Action DAO (Module 10 v2). * * Room DAO for [UndoActionEntity]. Used by [com.roshan.persona.system.undo.PersistentUndoStack] * to persist reversible system operations across app restarts. * * ## LIFO semantics * * The undo stack is LIFO (last-in-first-out). The latest inserted row is the * first to be popped. We use auto-incrementing `id` for ordering — higher id * = more recent. * * ## Bounded size * * [trim] keeps only the last [PersistentUndoStack.MAX_UNDO_ACTIONS] (50) rows. * Without this, the stack would grow unbounded over a long session. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Persistent Undo Stack — Schema</a> */@Daointerface UndoActionDao {    /** Insert a new undo action. Returns the auto-generated row ID. */    @Insert(onConflict = OnConflictStrategy.REPLACE)    suspend fun insert(entity: UndoActionEntity): Long    /** Get the most recently inserted undo action (top of the LIFO stack). */    @Query("SELECT * FROM undo_actions ORDER BY id DESC LIMIT 1")    suspend fun getLatest(): UndoActionEntity?    /** Get the N most recent undo actions (for UI history list). */    @Query("SELECT * FROM undo_actions ORDER BY id DESC LIMIT :limit")    suspend fun getRecent(limit: Int): List<UndoActionEntity>    /** Delete a specific undo action by row ID (after successful undo). */    @Query("DELETE FROM undo_actions WHERE id = :id")    suspend fun deleteById(id: Long)    /** Keep only the most recent N rows; delete the rest. */    @Query("DELETE FROM undo_actions WHERE id NOT IN " +        "(SELECT id FROM undo_actions ORDER BY id DESC LIMIT :keepCount)")    suspend fun trim(keepCount: Int)    /** Delete all undo actions (Settings → Privacy → Clear action history). */    @Query("DELETE FROM undo_actions")    suspend fun clear()    /** Count of stored undo actions. */    @Query("SELECT COUNT(*) FROM undo_actions")    suspend fun count(): Int}